class Solution {
public:
    int sortableIntegers(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;

        auto check = [&](int k) -> bool {
            int prev_max = 0;
            for (int i = 0; i < n; i += k) {
                int drops = 0;
                int cur_min = nums[i];
                int cur_max = nums[i];
                for (int j = 0; j < k; ++j) {
                    int cur = nums[i + j];
                    int nxt = nums[i + (j + 1 == k ? 0 : j + 1)];
                    if (cur > nxt) {
                        drops++;
                        if (drops > 1) return false;
                    }
                    if (cur < cur_min) cur_min = cur;
                    if (cur > cur_max) cur_max = cur;
                }
                if (i > 0 && cur_min < prev_max) {
                    return false;
                }
                prev_max = cur_max;
            }
            return true;
        };

        for (int k = 1; k * k <= n; ++k) {
            if (n % k == 0) {
                if (check(k)) {
                    ans += k;
                }
                if (k * k != n) {
                    if (check(n / k)) {
                        ans += n / k;
                    }
                }
            }
        }

        return ans;
    }
};
